statement_raw:
\begin{thema}{Γ}
Στο σχήμα δίνεται η γραφική παράσταση $C_f$ μιας δύο φορές παραγωγίσιμης συνάρτησης $f$ ορισμένης στο $[0, 6]$. Η $f$ τέμνει τον $x'x$ μόνο στα σημεία $x = 0$ και $x = 4$, παρουσιάζει μέγιστο $f(2) = 3$ και αλλαγή κυρτότητας κοντά στο $x=3$. Είναι γνωστό ότι $f(6) = -2$.

\begin{center}
\begin{tikzpicture}[scale=0.7]
  \draw[help lines, gray!30] (-1,-3) grid (7,4);
  \draw[-latex] (-1.3,0) -- (7.3,0) node[right] {$x$};
  \draw[-latex] (0,-3.3) -- (0,4.3) node[above] {$y$};
  \foreach \x in {1,2,3,4,5,6}
    \draw (\x,0.1) -- (\x,-0.1) node[below,font=\footnotesize] {$\x$};
  \foreach \y in {-2,-1,1,2,3}
    \draw (0.1,\y) -- (-0.1,\y) node[left,font=\footnotesize] {$\y$};
  % curve
  \draw[very thick, blue!70!black, smooth, tension=0.55]
    plot coordinates {(0,0) (0.5,1) (1,2.2) (1.5,2.8) (2,3) (2.5,2.8) (3,2) (3.5,1) (4,0) (5,-1.5) (6,-2)};
  % shaded positive area
  \fill[orange!12, opacity=0.5, smooth, tension=0.55]
    (0,0) -- plot coordinates {(0,0) (0.5,1) (1,2.2) (1.5,2.8) (2,3) (2.5,2.8) (3,2) (3.5,1) (4,0)} -- cycle;
  % shaded negative area
  \fill[red!10, opacity=0.5, smooth, tension=0.55]
    (4,0) -- plot coordinates {(4,0) (5,-1.5) (6,-2)} -- (6,0) -- cycle;
  \filldraw[blue!70!black] (0,0) circle (2pt);
  \filldraw[blue!70!black] (2,3) circle (2pt) node[above,font=\footnotesize] {$(2,3)$};
  \filldraw[blue!70!black] (4,0) circle (2pt);
  \filldraw[blue!70!black] (6,-2) circle (2pt) node[below right,font=\footnotesize] {$(6,-2)$};
  \node[blue!70!black] at (5.5,2) {$C_f$};
\end{tikzpicture}
\end{center}

\begin{erwthma}
  \item Να μελετήσετε τη μονοτονία και τα ακρότατα της $f$. Ποιο είναι το ολικό μέγιστο και ποιο το ολικό ελάχιστο;
  \item Από τη γραφική, να αποδείξετε ότι υπάρχει $\xi \in (0, 4)$ ώστε $f'(\xi) = 0$ (Θ. \eng{Rolle}). Πόσα τέτοια $\xi$ βλέπετε;
  \item Χρησιμοποιώντας τα σκιασμένα χωρία, να αποδείξετε ότι $\dint_0^6 f(x) dx > 0$ (δηλ. το πράσινο εμβαδόν είναι μεγαλύτερο του κόκκινου).
  \item Ένα σημείο $M(x, f(x))$ κινείται στην $C_f$ για $x > 4$ με $x'(t) = 1$ μον/$\sec$. Τη στιγμή που $x = 5$, η εφαπτομένη σχηματίζει αρνητική κλίση (εκτίμηση $f'(5) \approx -1$). Να βρείτε τον ρυθμό μεταβολής της τεταγμένης $y'(t)$.
\end{erwthma}
\end{thema}

